t.script:
// Device ID Logic
function getDeviceId() {
    let did = localStorage.getItem('wuchang_device_id');
    if (!did) {
        did = 'DEV-' + Math.random().toString(36).substr(2, 9).toUpperCase() + '-' + Date.now();
        localStorage.setItem('wuchang_device_id', did);
    }
    return did;
}

const deviceId = getDeviceId();
const video = document.getElementById('video-feed');
const canvas = document.getElementById('capture-canvas');

// Initialize Camera
if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia({ video: true }).then(function(stream) {
        video.srcObject = stream;
        video.play();
    });
}

async function verifyIdentity() {
    const btn = document.getElementById('btn-verify');
    const msg = document.getElementById('status-message');
    btn.disabled = true;
    btn.innerText = 'Scanning...';
    msg.style.display = 'none';

    // Capture Image
    const context = canvas.getContext('2d');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    context.drawImage(video, 0, 0, canvas.width, canvas.height);
    const imageData = canvas.toDataURL('image/png');

    // Send to Backend
    try {
        const response = await fetch('/wuchang/brother/verify', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: "2.0",
                method: "call",
                params: {
                    device_id: deviceId,
                    image_data: imageData
                }
            })
        });
        const result = await response.json();

        if (result.result && result.result.success) {
            document.getElementById('verification-section').style.display = 'none';
            document.getElementById('command-section').style.display = 'block';
            updateStatus();
        } else {
            msg.className = 'alert alert-danger';
            msg.innerText = result.result ? result.result.message : 'Verification Failed';
            msg.style.display = 'block';
            btn.disabled = false;
            btn.innerText = 'Try Again';
        }
    } catch (error) {
        console.error(error);
        btn.disabled = false;
        btn.innerText = 'Try Again';
    }
}

async function executeCommand(cmd) {
    try {
        const response = await fetch('/wuchang/brother/execute', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: "2.0",
                method: "call",
                params: {
                    device_id: deviceId,
                    command: cmd
                }
            })
        });
        const result = await response.json();
        if (result.result && result.result.status === 'success') {
            alert(result.result.message);
            updateStatus();
        } else {
            alert('Error: ' + (result.result ? result.result.message : 'Unknown error'));
        }
    } catch (e) {
        console.error(e);
    }
}

async function updateStatus() {
    const response = await fetch('/wuchang/brother/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                device_id: deviceId,
                command: 'get_status'
            }
        })
    });
    const result = await response.json();
    if (result.result && result.result.status === 'success') {
        document.getElementById('sys-state').innerText = result.result.state;
        document.getElementById('sys-score').innerText = result.result.hallucination_score;
        document.getElementById('sys-msg').innerText = result.result.last_message;
    }
}
